import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  test('SCRATCH: registry-leg ref keeps project through _throughCustomEntry',
      () {
    final entry = CustomProviderEntry(
      name: 'codemie-lab',
      apiType: 'openai',
      baseUrl: 'https://codemie.lab.epam.com/code-assistant-api/v1',
      modelId: 'codemie-model',
      project: 'entry-project',
    );
    // Case 1: explicit project on the ref, registry-leg defaults applied
    // (ref omits baseUrl and apiKeyName → rebuilt through the entry).
    final resolver = ModelRolesResolver(
      config: ModelRolesConfig(
        roles: {
          'default': [
            ModelRef(
              provider: 'codemie-lab',
              modelId: 'codemie-model',
              project: 'demo-project',
            ),
          ],
        },
      ),
      secrets: const {'OPENAI_API_KEY': 'cm-key'},
      customProviders: [entry],
      streamFactory: (kind, key) => (model, context, {cancelToken}) async* {},
    );
    final model = resolver.chainFor('default')!.single.model;
    // ignore: avoid_print
    print('explicit-ref project → header: '
        '${model.headers?['x-codemie-project']}');

    // Case 2: ref WITHOUT an explicit project naming an entry that carries
    // one — does the entry's project default onto the chain model?
    final resolver2 = ModelRolesResolver(
      config: ModelRolesConfig(
        roles: {
          'default': [
            ModelRef(provider: 'codemie-lab', modelId: 'codemie-model'),
          ],
        },
      ),
      secrets: const {'OPENAI_API_KEY': 'cm-key'},
      customProviders: [entry],
      streamFactory: (kind, key) => (model, context, {cancelToken}) async* {},
    );
    final model2 = resolver2.chainFor('default')!.single.model;
    // ignore: avoid_print
    print('plain-ref → header: ${model2.headers?['x-codemie-project']}');
    print('plain-ref baseUrl: ${model2.baseUrl}');
  });
}

